package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.chronicle.*; import com.mojang.blaze3d.platform.InputConstants; import net.fabricmc.api.ClientModInitializer; import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper; import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents; import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking; import net.minecraft.client.KeyMapping; import org.lwjgl.glfw.GLFW;
public final class TheWorldRemembersClient implements ClientModInitializer{private static volatile VoicePacket lastVoice; private static volatile String chronicles; private static KeyMapping openChronicles; public static VoicePacket lastVoice(){return lastVoice;} public void onInitializeClient(){ClientPlayNetworking.registerGlobalReceiver(VoicePacket.TYPE,(payload,context)->lastVoice=payload);ClientPlayNetworking.registerGlobalReceiver(ChroniclePacket.TYPE,(payload,context)->{chronicles=payload.content();net.minecraft.client.Minecraft.getInstance().execute(()->net.minecraft.client.Minecraft.getInstance().setScreen(new ChronicleScreen(chronicles)));});openChronicles=KeyBindingHelper.registerKeyBinding(new KeyMapping("key.the_world_remembers.chronicles",InputConstants.Type.KEYSYM,GLFW.GLFW_KEY_J,"key.categories.the_world_remembers"));ClientTickEvents.END_CLIENT_TICK.register(client->{while(openChronicles.consumeClick())ClientPlayNetworking.send(new ChronicleRequestPacket());});}}
